-- Check if tempstabidx might need to be multiplied by 100
-- Also check handleevents vs critevents
SELECT sensortrack, tempdevcount, critevents, handleevents, tempstabidx FROM sensordata WHERE sensortrack IN (1,2,3);

-- Check if there's a containriskidx or similar in any table
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%risk%' OR column_name LIKE '%cri%';

